import { Component } from 'react'
import PropTypes from 'prop-types'
import { Modal, Button } from '../../../../../components'
import { APPLICATION_LANG } from '../../lang'
import { SelectedAddonsModalStyle } from './index.style'
import AmountTitle from '../../../../../components/AmountTitle'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { formatMoney } from '../../../../../helpers/utility'

class SelectedAddonsListModal extends Component {
  static propTypes = {
    data: PropTypes.array,
    totalAddonPremium: PropTypes.number,
    showAddonsListModal: PropTypes.bool,
    onClose: PropTypes.func
  }

  render () {
    const { showAddonsListModal, onClose, totalAddonPremium, data = [] } = this.props
    return (
      <Modal
        heading={APPLICATION_LANG.additionalPackage}
        isOpen={showAddonsListModal}
        onClose={onClose}
      >
        <SelectedAddonsModalStyle>
          {
            !!data.length && data.map(adddon => (
              <AmountTitle
                key={adddon.add_on_code}
                title={adddon.add_on_name}
                showAddonIcon={!adddon.premium}
                amount={formatMoney((adddon.premium || '0'), 0)}
                color={AgentColorPallette.black}
              />
            ))
          }
          <hr />
          <AmountTitle
            title={APPLICATION_LANG.totalAddionalCost}
            amount={formatMoney((totalAddonPremium || '0'), 0)}
            color={AgentColorPallette.darkGold}
          />
          <Button handleClick={onClose} className='margin-top'>
            {LANG_STRINGS.okay}
          </Button>
        </SelectedAddonsModalStyle>
      </Modal>
    )
  }
}

export default SelectedAddonsListModal
