import { useState } from 'react'
import { PROP_DETAIL_TABS } from '../../constants'
import { PropDetailTabStyle } from './index.style'

function PropDetailTabs (props) {
  const [activeTab, setActiveState] = useState('benefit')

  const handleTabClick = (tabType) => {
    // on tab click show the active tab
    setActiveState(tabType)
    props.onTabClick(tabType)
  }

  return (
    <PropDetailTabStyle>
      {
        PROP_DETAIL_TABS.map(tab => (
          <div
            className={`tab-title ${(activeTab === tab.type) && 'bottom-slider'}`}
            key={tab.type}
            id={`property${tab.type}Tab`}
            onClick={() => handleTabClick(tab.type)}
          >
            {tab.name}
          </div>
        ))
      }
    </PropDetailTabStyle>
  )
}

export default PropDetailTabs
