import React from 'react'
import { get } from 'lodash'
import { MitraCard } from '../../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'

const ClaimDetails = ({ claims }) => {
  return (
    <MitraCard>
      {
        claims.map((claimItem, claimIndex) => (
          <div key={`claim_item_${claimIndex}`} style={{ marginBottom: '20px' }}>
            <CustomText 
              size='16px' 
              lineHeight={1.5} 
              color={AgentColorPallette.black}
              style={{ fontWeight: 'bold', marginBottom: '10px' }}
            >
              {claimItem.title}
            </CustomText>
            {
              claimItem.description && (
                <CustomText 
                  size='13px' 
                  lineHeight={1.5} 
                  color={AgentColorPallette.black}
                  style={{ marginBottom: '8px' }}
                >
                  {claimItem.description}
                </CustomText>
              )
            }
            {
              get(claimItem, 'items', []).length > 0 && (
                <ul style={{ margin: '5px 0', paddingLeft: '20px' }}>
                  {
                    claimItem.items.map((item, itemIndex) => (
                      <li key={`claim_item_list_${claimIndex}_${itemIndex}`}>
                        <CustomText 
                          size='13px' 
                          lineHeight={1.5} 
                          color={AgentColorPallette.black}
                        >
                          {item}
                        </CustomText>
                      </li>
                    ))
                  }
                </ul>
              )
            }
          </div>
        ))
      }
    </MitraCard>
  )
}

export default ClaimDetails
