import { createRef, Component } from 'react'
import PropTypes from 'prop-types'
import { APPLICATION_LANG } from '../../lang'
import { Modal, CustomText, Button } from '../../../../../components'
import { DiscountModalStyle, UserInputDiscountContainer } from './index.style'
import SwitchButton from '../../../../../components/SwitchButton'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../lang'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import NumericInput from '../../../../../components/NumericInput'
import AmountTitle from '../../../../../components/AmountTitle'
import { Row } from '../../../../../commonStyle/index.style'

class DiscountModal extends Component {
  static propTypes = {
    showDiscountModal: PropTypes.bool,
    onSubmitDiscount: PropTypes.func,
    commission: PropTypes.number,
    maxDiscount: PropTypes.number,
    subTotal: PropTypes.number,
    comissionPercent: PropTypes.number,
    onClose: PropTypes.func,
    currentDiscount: PropTypes.number
  }

  constructor (props) {
    super(props)
    this.state = {
      btnType: 'nominal',
      discount: props.currentDiscount || 0,
      percentagePlaceholder: APPLICATION_LANG.percentagePlaceholder.replace('XXX', `${props.comissionPercent}%`),
      discountError: false
    }
    this.inputRef = createRef()
  }

  componentWillUnmount () {
    this.setState({
      btnType: 'nominal',
      discount: 0,
      discountError: false
    })
  }

  submitDiscount = () => {
    this.props.onSubmitDiscount(this.state.discount)
  }

  handlePercentageValue = (value) => {
    const { btnType } = this.state
    const { maxDiscount, comissionPercent } = this.props
    const isPercentageType = btnType === 'percentage'
    
    if (!value || value === 0 || value === '') {
      this.setState({
        discountError: false,
        discount: 0
      })
      return
    }
    
    const numericValue = parseFloat(value)
    const isValidPercentage = isPercentageType ? (numericValue <= comissionPercent) : (numericValue <= maxDiscount)
    
    if (!isValidPercentage) {
      this.setState({
        discountError: true
      })
      return false
    }

    this.setState({
      discountError: false,
      discount: this.getDiscountAmount(numericValue)
    })
  }

  handleSwitchBtnChange = (value) => {
    this.setState({
      btnType: value,
      discountError: false,
      discount: 0
    })
    this.inputRef.current.resetInputValue()
  }

  getDiscountAmount = (value = 0) => {
    const { btnType } = this.state
    const { subTotal } = this.props
    
    if (btnType === 'nominal') {
      return parseFloat(value) || 0
    } else {
      // For percentage, calculate the discount amount based on subTotal
      const percentageValue = parseFloat(value) || 0
      return Math.floor(subTotal * (percentageValue / 100))
    }
  }

  render () {
    const { showDiscountModal, onClose, commission, maxDiscount, comissionPercent } = this.props
    const { btnType, discountError, discount, percentagePlaceholder } = this.state
    const isPercentageType = btnType === 'percentage'
    return (
      <Modal
        heading={APPLICATION_LANG.giveDiscountPromos}
        isOpen={showDiscountModal}
        onClose={onClose}
      >
        <DiscountModalStyle>
          <CustomText
            color={AgentColorPallette.black}
            size='14px'
            weight={800}
            bottom='10px'
          >
            {APPLICATION_LANG.enteredDiscountPrice}
          </CustomText>
          <SwitchButton
            left={{
              text: LANG_STRINGS.nominal,
              value: 'nominal'
            }}
            right={{
              text: LANG_STRINGS.percentage,
              value: 'percentage'
            }}
            selectedValue='left'
            onChange={this.handleSwitchBtnChange}
          />
          {
            <UserInputDiscountContainer isError={discountError}>
              {
                !isPercentageType && <div className='rupee-icon'>Rp</div>
              }
              <NumericInput
                ref={this.inputRef}
                name='percentageInput'
                onChange={this.handlePercentageValue}
                id='percentageInput'
                type={isPercentageType ? 'discount' : 'amount'}
                className={isPercentageType ? 'numeric-input' : 'numeric-input-nominal'}
                placeholder={isPercentageType ? percentagePlaceholder : APPLICATION_LANG.maxAmontYourComission}
                maxValue={isPercentageType ? comissionPercent : maxDiscount}
                maxLength={isPercentageType ? 3 : 10}
                decimal={isPercentageType ? 2 : 0}
                isNotSuffix={!isPercentageType}
                defaultValue={!isPercentageType ? this.props.currentDiscount : undefined}
              />
              {
                isPercentageType && <div className='percentage-icon'>%</div>
              }
            </UserInputDiscountContainer>
          }
          {
            discountError && (
              <CustomText
                color={AgentColorPallette.errorDark}
                size='10px'
                lineHeight={1.5}
                top='4px'
              >
                {ERROR_LANG.maxDiscountError}
              </CustomText>
            )
          }
          <div className='discount-amounts'>
            <AmountTitle
              title={APPLICATION_LANG.transactionAmount}
              amount={commission}
              className='discount-margin-btm'
            />
            <AmountTitle
              title={LANG_STRINGS.discount}
              amount={discount || '0'}
              amountPrefix='- Rp '
              color={AgentColorPallette.errorDark}
            />
          </div>
          <AmountTitle
            title={APPLICATION_LANG.finalComission}
            amount={commission - discount}
          />
          <Row justify='space-around'>
            <Button
              handleClick={onClose}
              color={AgentColorPallette.white}
              backgroundColor={AgentColorPallette.cyanBlue}
              className='discount-btn'
            >
              {LANG_STRINGS.cancel}
            </Button>
            <Button
              className='discount-btn'
              disabled={discountError || !discount}
              handleClick={this.submitDiscount}
            >
              {LANG_STRINGS.use}
            </Button>
          </Row>
        </DiscountModalStyle>
      </Modal>
    )
  }
}

export default DiscountModal
