import { PROPERTY_PROTECTION, PROPERTY_PROTECTION_BASIC } from '../../../../constants/pkgCode'

export const getPropPkgRequestData = (draft) => {
  if (!draft) {
    return
  }

  return {
    code: PROPERTY_PROTECTION,
    package_type: PROPERTY_PROTECTION_BASIC,
    province_code: draft.province_code,
    province_name: draft.province_name,
    city_code: draft.city_code,
    city_name: draft.city_name,
    postal_code: draft.postal_code,
    property_address: draft.property_address,
    zone: draft?.property_data?.zone,
    start_date: draft.start_date,
    end_date: draft.end_date,
    sum_insured: draft.sum_insured,
    property_data: draft.property_data,
    customer_data: draft.customer_data,
    questionnaire: draft.questionnaire,
  }
}
