import { Component } from 'react'
import PropTypes from 'prop-types'
import NumberFormat from 'react-number-format'
import { AmountStyle } from './index.style'
import { Row, DisplayCircleIcon } from '../../../../../commonStyle/index.style'
import { CustomText, Button } from '../../../../../components'
import { APPLICATION_LANG } from '../../lang'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { INFO, CLOSE_ICON } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import SelectedAddonsListModal from '../SelectedAddonsListModal'
import { formatMoney } from '../../../../../helpers/utility'
import { get } from 'lodash'

class AmountDistribution extends Component {
  static propTypes = {
    pkgDetail: PropTypes.object,
    instalmentDetails: PropTypes.object,
    discount: PropTypes.number,
    isHideDiscountIcon: PropTypes.bool,
    useInstalment: PropTypes.bool,
    showAgentCommission: PropTypes.bool,
    hideNull: PropTypes.bool,
    id: PropTypes.string,
    onDiscountAddClick: PropTypes.func,
    onDiscountRemove: PropTypes.func,
    subTitle: PropTypes.string
  }

  state = {
    showAddonsListModal: false
  }

  handleCloseModal = () => {
    this.setState({
      showAddonsListModal: false
    })
  }

  handleShoweModal = () => {
    this.setState({
      showAddonsListModal: true
    })
  }

  getNumberContainer = (number, color = AgentColorPallette.black, prefix = 'Rp ') => {
    return (
      <CustomText
        size='14px'
        weight={800}
        color={color}
      >
        <NumberFormat
          // hintText="Masukan Harga"
          thousandSeparator='.'
          decimalSeparator=','
          className='format-input'
          prefix={prefix}
          value={number}
          displayType='text'
        />
      </CustomText>
    )
  }

  getAmountName = (title, color = AgentColorPallette.black, weight) => {
    return (
      <CustomText
        color={color}
        size='14px'
        weight={weight}
      >
        {title}
      </CustomText>
    )
  }

  getTotalAmount = (instalmentDetails = {}, serviceFee) => {
    return instalmentDetails.payable_amount + instalmentDetails.admin_fee + instalmentDetails.stamp_duty - instalmentDetails.discount + serviceFee
  }

  getAmountContainer = (title, amount, className, color = AgentColorPallette.black, amountPrefix, subTitle) => {
    if (amount || subTitle) {
      return (
        <div className={className}>
          <Row justify='space-between'>
            {this.getAmountName(title, color)}
            {this.getNumberContainer(formatMoney(amount, 0, ''), color, amountPrefix)}
          </Row>
          {
            subTitle && (
              <CustomText color={color} size='10px'>
                {subTitle}
              </CustomText>
            )
          }
        </div>
      )
    }

    return null
  }

  render () {
    const {
      onDiscountAddClick, onDiscountRemove, pkgDetail, id,
      discount = 0, isHideDiscountIcon = false, showAgentCommission = true,
      hideNull = false, isManualOrder, useInstalment, instalmentDetails
    } = this.props
    return (
      <AmountStyle>
        {
          this.getAmountContainer(
            useInstalment ? `${LANG_STRINGS.basicPremium} Cicilan ${instalmentDetails?.serial_number}` : APPLICATION_LANG.basicPremium,
            useInstalment ? instalmentDetails.payable_amount : (isManualOrder ? pkgDetail.net_premium : (pkgDetail.basic_premium || pkgDetail.total_bill)),
            'margin-btm'
          )
        }
        {
          !!get(pkgDetail, 'add_ons.length', 0) && !isManualOrder && (
            <Row justify='space-between'>
              <Row>
                {this.getAmountName(APPLICATION_LANG.additionalPackage)}
                &nbsp;
                {
                  (
                    <DisplayCircleIcon width='20px' height='20px' onClick={this.handleShoweModal}>
                      <img src={INFO} alt='' />
                    </DisplayCircleIcon>
                  )
                }
              </Row>
              {this.getNumberContainer(useInstalment ? instalmentDetails.add_on_premium : pkgDetail.add_on_premium)}
            </Row>
          )
        }
        {
          this.getAmountContainer(
            APPLICATION_LANG.subTotal,
            (useInstalment ? instalmentDetails.sub_total : (isManualOrder ? pkgDetail.net_premium : pkgDetail.sub_total)),
            'sub-total',
            AgentColorPallette.mustard
          )
        }
        {
          this.getAmountContainer(
            APPLICATION_LANG.stampDuty,
            useInstalment ? instalmentDetails.stamp_duty : pkgDetail.stamp_duty,
            'margin-btm'
          )
        }
        {
          this.getAmountContainer(
            APPLICATION_LANG.tax,
            useInstalment ? instalmentDetails.tax : pkgDetail.tax,
            'margin-btm'
          )
        }
        {
          this.getAmountContainer(
            APPLICATION_LANG.adminFee,
            useInstalment ? instalmentDetails.admin_fee : pkgDetail.admin_fee,
            'margin-btm',
            AgentColorPallette.black
          )
        }
        {
          this.getAmountContainer(
            APPLICATION_LANG.serviceFee,
            pkgDetail.service_fee,
            'margin-btm',
            AgentColorPallette.black
          )
        }
        {
          !hideNull && (
            <Row justify='space-between' align='center'>
              <Row>
                {this.getAmountName(LANG_STRINGS.discount, AgentColorPallette.errorDark)}
                &nbsp;
                {
                  (!!discount && !isHideDiscountIcon) && (
                    <img onClick={onDiscountRemove} id={`${id}_DiscountRemove`} width='18px' src={CLOSE_ICON} alt='' />
                  )
                }
              </Row>
              {
                (!discount && !isHideDiscountIcon) ? (
                  <Button className='add-discount-btn' id={`${id}_DiscountAdd`} handleClick={onDiscountAddClick}>
                    {LANG_STRINGS.add}
                  </Button>
                ) : (
                  this.getNumberContainer(
                    useInstalment ? instalmentDetails.discount : discount,
                    AgentColorPallette.errorDark,
                    '- Rp '
                  )
                )
              }
            </Row>
          )
        }
        {
          (pkgDetail.payment_by === 'AGENT' && showAgentCommission) &&
            this.getAmountContainer(
              LANG_STRINGS.fromYourCommission,
              (pkgDetail.current_commission_used ? (pkgDetail.agent_commission - discount) : pkgDetail.current_commission_used),
              'border-top margin-btm',
              AgentColorPallette.errorDark,
              '- Rp ',
              (pkgDetail.current_commission_used ? '' : LANG_STRINGS.canNotUsedBecauseOfInitialBalance)
            )
        }
        {
          this.getAmountContainer(
            LANG_STRINGS.useOfBalance,
            pkgDetail.commission_used,
            'border-top margin-btm',
            AgentColorPallette.errorDark,
            '- Rp '
          )
        }
        {
          this.getAmountContainer(
            LANG_STRINGS.useOfPoint,
            (pkgDetail.point_used),
            `${pkgDetail.commission_used ? '' : 'border-top'} 'margin-btm'`,
            AgentColorPallette.errorDark,
            '- Rp '
          )
        }
        <Row justify='space-between' className='total-amount'>
          <div>
            {this.getAmountName(LANG_STRINGS.totalBill, AgentColorPallette.darkerGold, 800)}
          </div>
          {
            this.getNumberContainer(
              (useInstalment ? this.getTotalAmount(instalmentDetails, pkgDetail.service_fee) : (pkgDetail.total_bill - discount)), AgentColorPallette.darkerGold)
          }
        </Row>
        {this.props.subTitle && (
          <Row justify='space-between' className="subtitle">
            <CustomText color={AgentColorPallette.fontSemiGrey}>
              {this.props.subTitle}
            </CustomText>
          </Row>
        )}
        <SelectedAddonsListModal
          data={pkgDetail.add_ons}
          totalAddonPremium={pkgDetail.add_on_premium}
          showAddonsListModal={this.state.showAddonsListModal}
          onClose={this.handleCloseModal}
        />
      </AmountStyle>
    )
  }
}

export default AmountDistribution
