import { useState, useEffect } from 'react'
import { useHistory, useParams } from 'react-router'
import { connect } from 'react-redux'
import { isEmpty } from 'lodash'
import { BottomActionContainerStyle, Row } from '../../../../../commonStyle/index.style'
import { Button, Container } from '../../../../../components'
import SendQuotationModal from '../../../../../components/SendQuotationModal'
import StepsHeader from '../../../../../components/StepsHeader'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyActions from '../../../../../redux/policy/action'
import { getPropPkgRequestData } from '../../helper'
import DiscountModal from '../../../Application/components/DiscountModal'
import AmountDistribution from '../../../Application/components/AmountDistribution'
import { PolicyContextProvider } from '../../../Policy/context'
import { PROPERTY_LANG } from '../../lang'
import useDraftApi from '../hooks/useDraftApi'
import PropDetailTabs from '../components/PropDetailTabs'
import PropPkgDetailHeader from '../components/PropPkgDetailHeader'
import { BenefitDetails, TermsConditions, ClaimDetails } from './components'
import { PropertyPkgDetailStyle } from './index.style'

const PropertyPkgDetail = (props) => {
  const { getPackageDetail, packageDetail = {}, packageDetailLoading } = props

  const history = useHistory()
  const { draftId } = useParams()
  const [activeViewTab, setActiveViewTab] = useState('benefit')
  const [showDiscountModal, setShowDiscountModal] = useState(false)
  const [showQuotationModal, setShowQuotationModal] = useState(false)
  const [selectedBranch, setSelectedBranch] = useState({})
  const [discount, setDiscount] = useState(0)
  const [draftPolicyDetails, setDraftPolicyDetails] = useState({})

  const { isGetDraftLoader, isSaveLoader, handleSaveToDraft } = useDraftApi({
    draftId: draftId,
    onGetDraftDetailSuccess: (data) => {
      setDraftPolicyDetails(data.policy_details || data)
    },
    onSaveSuccess: ({ draftId }) => {
      history.push(`/property/property-protection/5/form/${draftId}`)
    }
  })

  useEffect(() => {
    if (draftPolicyDetails?.discount) {
      setDiscount(draftPolicyDetails.discount)
    }
  }, [draftPolicyDetails?.discount])

  useEffect(() => {
    if (draftPolicyDetails && packageDetail && Object.keys(draftPolicyDetails).length > 0 && Object.keys(packageDetail).length > 0) {
      const updatedData = {
        ...draftPolicyDetails,
        purchase_type: 'new-purchase',
        package_data: packageDetail,
        discount: discount,
      }
      handleSaveToDraft(updatedData, 'package_details', 'package_details', false)
    }
  }, [handleSaveToDraft, draftPolicyDetails, packageDetail, discount]) 

  useEffect(() => {
    if (discount !== 0) {
      const requestData = getPropPkgRequestData({
        ...draftPolicyDetails,
        discount: discount ? parseInt(discount) : 0
      })
      getPackageDetail({
        ...draftPolicyDetails,
        body: requestData,
        packageCode: draftPolicyDetails.package_code
      })
    }
  }, [discount, getPackageDetail, draftPolicyDetails])

  useEffect(() => {
    if (Object.keys(draftPolicyDetails).length === 0) {
      return
    }

    const requestData = getPropPkgRequestData(draftPolicyDetails)
    if (!requestData || Object.keys(requestData).length === 0) {
      history.replace('/property/property-protection/1/form')
      return
    }

    getPackageDetail({
      body: requestData,
      packageCode: draftPolicyDetails.package_code
    })
  }, [history, getPackageDetail, draftPolicyDetails])

  const handleTabClick = (tab) => {
    setActiveViewTab(tab)
  }

  const handleBuyPkg = () => {
    const updatedData = {
      ...draftPolicyDetails,
      purchase_type: 'new-purchase',
      package_data: packageDetail,
      discount: discount,
    }
    handleSaveToDraft(updatedData, 'insured_details', 'customer_data', true)
  }

  const handleToggleDiscountModal = () => {
    setShowDiscountModal(prevState => !prevState)
  }

  const handleDiscountSubmit = (discountValue) => {
    setDiscount(discountValue)
    setShowDiscountModal(false)
  }

  const {
    tnc = [], benefit = {}, claims = [],
    commission, max_discount: maxDiscount,
    discount_percentage: discountPercent,
    sub_total: subTotal
  } = packageDetail
  let branch = selectedBranch

  if (isEmpty(branch)) {
    branch = packageDetail?.provider?.headquarter_branch
  }

  return (
    <Container
      title={PROPERTY_LANG.propertyInsurance}
      loader={isGetDraftLoader || packageDetailLoading || isSaveLoader}
      hideBottomTabs
      showCloseIcon
      onClose={() => history.push('/dashboard')}
      onBackClick={() => history.push(`/property/property-protection/3/packages/${draftId}`)}
    >
      <PropertyPkgDetailStyle>
        <StepsHeader
          current='4'
          totalSteps='6'
          leftText={PROPERTY_LANG.chooseInsurance}
          className='steps-header'
        />
        <PropPkgDetailHeader
          pkgDetail={packageDetail}
          selectedBranch={branch}
          onBranchSelect={(branch) => setSelectedBranch(branch)}
          draftPolicyDetails={draftPolicyDetails}
        />
        <PropDetailTabs onTabClick={handleTabClick} />
        <div className='prop-tab-details'>
          {activeViewTab === 'benefit' && <BenefitDetails benefit={benefit} />}
          {activeViewTab === 'termsConditions' && <TermsConditions tnc={tnc} />}
          {activeViewTab === 'claim' && <ClaimDetails claims={claims} />}
        </div>
        <BottomActionContainerStyle
          padding='0'
          direction='column'
          align='stretch'
          position='relative'
        >
          {
            !isEmpty(packageDetail) && (
              <AmountDistribution
                onDiscountAddClick={handleToggleDiscountModal}
                onDiscountRemove={() => setDiscount(0)}
                pkgDetail={{
                  ...packageDetail,
                  tax: 0
                }}
                id='propertyPackageDetailStep_3'
                discount={discount}
              />
            )
          }
          <Row className='prop-pkg-detail-btn-box' justify='space-between'>
            <Button
              onClick={() => setShowQuotationModal(true)}
              backgroundColor={AgentColorPallette.cyanBlue}
              color={AgentColorPallette.white}
              id='property-detail-offer-click'
              className='pkg-detail-btn'
            >
              {LANG_STRINGS.sendOffer}
            </Button>
            <div className='space' />
            <Button
              onClick={handleBuyPkg}
              id='property-detail-agent-buy-pkg-click'
              className='pkg-detail-btn'
            >
              {LANG_STRINGS.buyThisPackage}
            </Button>
          </Row>
        </BottomActionContainerStyle>
        {
          showQuotationModal && (
            <SendQuotationModal
              providerBranch={branch}
              showQuotationModal={showQuotationModal}
              quotation={{
                premium: { period: 12 },
                discount: discount || 0
              }}
              pkgDetail={packageDetail}
              policyType={draftPolicyDetails?.customer_data?.type}
              id='propertyDetailPkgOfferStep-3'
              onClose={() => setShowQuotationModal(false)}
              draftId={draftId}
            />
          )
        }
        {
          showDiscountModal && (
            <DiscountModal
              showDiscountModal={showDiscountModal}
              onClose={handleToggleDiscountModal}
              commission={commission}
              maxDiscount={maxDiscount}
              subTotal={subTotal}
              comissionPercent={discountPercent}
              onSubmitDiscount={handleDiscountSubmit}
              currentDiscount={discount}
            />
          )
        }
      </PropertyPkgDetailStyle>
    </Container>
  )
}

function WrappedPropertyPkgDetail (props) {
  return (
    <PolicyContextProvider>
      <PropertyPkgDetail {...props} />
    </PolicyContextProvider>
  )
}

const { getPackageDetail } = PolicyActions

export default connect(
  (state) => ({
    packageDetailLoading: state.Loading.GET_PACKAGE_DETAIL,
    packageDetail: state.Policy.packageDetail
  }),
  {
    getPackageDetail
  }
)(WrappedPropertyPkgDetail)
