import { get } from 'lodash'
import { DisplayFlexCCC } from '../../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../../components'
import AmountTitle from '../../../../../../components/AmountTitle'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../lang'
import { PropPkgDetailHeaderStyle } from './index.style'
import { formatDate } from '../../../../../../helpers/formatDate'

function PropPkgDetailHeader (props) {
  const { pkgDetail = {}, draftPolicyDetails } = props
  const startDate = formatDate(draftPolicyDetails?.start_date, 'DD/MM/YYYY [12:00 Siang]')
  const endDate = formatDate(draftPolicyDetails?.end_date, 'DD/MM/YYYY [12:00 Siang]')

  return (
    <PropPkgDetailHeaderStyle>
      <DisplayFlexCCC>
        <img
          className='pkg-img'
          src={get(pkgDetail, 'provider.logo_url', '')}
          alt=''
        />
        <CustomText
          color={AgentColorPallette.regular}
          size='10px'
          weight={600}
          top='10px'
          textAlign='center'
        >
          {get(pkgDetail, 'provider.name', '')}
        </CustomText>
        <CustomText
          color={AgentColorPallette.regular}
          weight='800'
          size='15px'
          textAlign='center'
        >
          {get(pkgDetail, 'package.name', '')}
        </CustomText>
      </DisplayFlexCCC>
      <div className='pkg-premium-container'>
        <AmountTitle
          title={LANG_STRINGS.premium}
          amount={pkgDetail.basic_premium || pkgDetail.total_bill}
        />
        <div className='prop-price-separator' />
        <AmountTitle
          title={LANG_STRINGS.coverage}
          amount={pkgDetail?.total_sum_insured}
        />
        <div className='prop-price-separator' />
        <AmountTitle
          title={LANG_STRINGS.period}
          showText
          amount={(
            <>
              {`${startDate ?? ''} -`}
              <br/>
              {endDate ?? ''}
            </>
          )}
        />
        <div className='prop-price-separator' />
      </div>
    </PropPkgDetailHeaderStyle>
  )
}

export default PropPkgDetailHeader
