import React from 'react'
import { size } from 'lodash'
import { MitraCard } from '../../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../../components'
import DisclaimerBox from '../../../../../../components/DisclaimerBox'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'

const TermsConditions = ({ tnc }) => {
  if (!size(tnc?.data)) {
    return null
  }

  return (
    <MitraCard>
      <DisclaimerBox /><br />
      {
        tnc?.data?.map((section, sectionIndex) => (
          <div key={`section_${sectionIndex}`}>
            {section.main_heading && (
              <CustomText
                color={AgentColorPallette.black}
                size='16px'
                bottom='15px'
                lineHeight={1.5}
                weight='600'
              >
                {section.main_heading}
              </CustomText>
            )}
            {
              section.tnc_list?.map((tncItem, tncIndex) => (
                <div key={`tnc_${sectionIndex}_${tncIndex}`} style={{ marginBottom: '20px' }}>
                  {tncItem.title && (
                    <CustomText
                      color={AgentColorPallette.black}
                      size='15px'
                      bottom='10px'
                      lineHeight={1.5}
                      weight='600'
                    >
                      {tncItem.title}
                    </CustomText>
                  )}
                  {tncItem.description && (
                    <CustomText
                      color={AgentColorPallette.black}
                      size='14px'
                      bottom='10px'
                      lineHeight={1.5}
                    >
                      {tncItem.description}
                    </CustomText>
                  )}
                  {tncItem.items?.length > 0 && (
                    <div style={{ paddingLeft: '15px' }}>
                      {tncItem.items?.map((item, itemIndex) => (
                        <CustomText
                          color={AgentColorPallette.black}
                          size='14px'
                          bottom='8px'
                          key={`item_${sectionIndex}_${tncIndex}_${itemIndex}`}
                          lineHeight={1.5}
                        >
                          {itemIndex + 1}. {item}
                        </CustomText>
                      ))}
                    </div>
                  )}
                  {tncItem.notes && (
                    <CustomText
                      color={AgentColorPallette.black}
                      size='14px'
                      bottom='10px'
                      lineHeight={1.5}
                    >
                      {tncItem.notes}
                    </CustomText>
                  )}
                </div>
              ))
            }
          </div>
        ))
      }
    </MitraCard>
  )
}

export default TermsConditions
