export const mapCategoryApiData = (
  data,
  draft,
  { provinces, propertyCities, propertyOccupation }
) => {
  const cityData = find(propertyCities, { city_code: data.city_code }) || {}
  const provinceData = find(provinces, { province_code: data.province_code }) || {}
  const occupationData =
    find(flatMap(propertyOccupation), {
      occupation_code: data.occupation_code,
    }) || {}
  return {
    province_code: provinceData.province_code,
    province_name: provinceData.province_name,
    city_code: cityData.city_code,
    city_name: cityData.city_name,
    postal_code: data.postal_code,
    property_address: data.property_address,
    location: data.property_address, // TODO: check if required
    zone: cityData.region,
    property_data: {
      ...(draft.property_data || {}),
      ...(data.property_data || {}),
      occupation_data: occupationData,
      no_of_floor: data.no_of_floor,
      zone: cityData.region, // zone is city region
    },
  }
}

