export const mapQuestionApiData = (questionData) => {
  const questionnaire = PROPERTY_QUESTION_DATA.map((q) => ({
    code: q.code,
    question: q.question,
    value: JSON.parse(questionData?.[q.code] || 'null'),
  })).filter((q) => q.value !== null && q.value !== undefined)
  return { questionnaire: questionnaire }
}

export const checkQuestionnaireAnswer = (questionData) => {
  // If answer is same as this, it means the product is available on binder
  // If different, then we don't have product for this -> show "No package available"
  const answerMap = {
    IS_FLOOD_HISTORY: false,
    IS_CAR_ACCESSIBLE: true,
    IS_FIRE_HISTORY: false,
    IS_NEAR_MARKET: false,
    IS_METAL_CONSTRUCTION: true,
    IS_WAREHOUSE_FLAMMABLE: false,
    IS_WAREHOUSE_HAVE_EXTINGUISHER: true,
  }
  let isInsideBinder = true
  questionData?.forEach((q) => {
    if (q.value !== answerMap[q.code]) {
      isInsideBinder = false
    }
  })
  return isInsideBinder
}

export const questionFormData = (data = {}) => {
  return {
    fields: PROPERTY_QUESTION_DATA.filter(
      (question) => !question.show || question.show.includes(data.property_data?.occupation_code)
    ).map((question) => {
      const dataValue = data.questionnaire?.find((v) => v.code === question.code)
      return {
        type: 'select',
        name: question.code,
        label: question.question,
        placeholder: PROPERTY_LANG.selectAnswers,
        required: true,
        data: [
          { value: 'true', display: LANG_STRINGS.yes },
          { value: 'false', display: LANG_STRINGS.no },
        ],
        dataKey: 'value',
        displayKey: 'display',
        defaultValue: dataValue ? JSON.stringify(dataValue.value) : null,
      }
    }),
  }
}

