export const mapOwnershipApiData = (data, draft) => {
  const isIndividualCustomer = data?.type === 'individual'
  const isCorporateCustomer = data?.type === 'corporate'
  return {
    customer_data: {
      ...(draft.customer_data || {}),
      type: data.type,
      ...(isIndividualCustomer ? { name: data.name } : {}),
      ...(isCorporateCustomer ? { corporate_data: { name: data.name } } : {}),
    },
  }
}

