import React from 'react'
import { get } from 'lodash'
import { MitraCard } from '../../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'

const BenefitDetails = ({ benefit }) => {
  return (
    <MitraCard>
      {
        get(benefit, 'data', []).map((benefitSection, sectionIndex) => (
          <div key={`benefit_section_${sectionIndex}`} style={{ marginBottom: '20px' }}>
            <CustomText 
              size='16px' 
              lineHeight={1.5} 
              color={AgentColorPallette.black}
              style={{ fontWeight: 'bold', marginBottom: '10px' }}
            >
              {benefitSection.main_heading}
            </CustomText>
            {
              get(benefitSection, 'benefit_list', []).map((benefitItem, itemIndex) => (
                <div key={`benefit_item_${sectionIndex}_${itemIndex}`} style={{ marginBottom: '15px', paddingLeft: '10px' }}>
                  <CustomText 
                    size='14px' 
                    lineHeight={1.5} 
                    color={AgentColorPallette.black}
                    style={{ fontWeight: '600', marginBottom: '5px' }}
                  >
                    {benefitItem.title}
                  </CustomText>
                  {
                    benefitItem.description && (
                      <CustomText 
                        size='13px' 
                        lineHeight={1.5} 
                        color={AgentColorPallette.black}
                        style={{ marginBottom: '8px' }}
                      >
                        {benefitItem.description}
                      </CustomText>
                    )
                  }
                  {
                    benefitItem.image_url && benefitItem.image_url.trim() !== '' && (
                      <div style={{ marginBottom: '8px' }}>
                        <img 
                          src={benefitItem.image_url} 
                          alt={benefitItem.title}
                          style={{ 
                            maxWidth: '100%', 
                            height: 'auto',
                            borderRadius: '4px'
                          }}
                        />
                      </div>
                    )
                  }
                  {
                    get(benefitItem, 'items', []).length > 0 && (
                      <ul style={{ margin: '5px 0', paddingLeft: '20px' }}>
                        {
                          benefitItem.items.map((item, itemListIndex) => (
                            <li key={`benefit_item_list_${sectionIndex}_${itemIndex}_${itemListIndex}`}>
                              <CustomText 
                                size='13px' 
                                lineHeight={1.5} 
                                color={AgentColorPallette.black}
                              >
                                {item}
                              </CustomText>
                            </li>
                          ))
                        }
                      </ul>
                    )
                  }
                </div>
              ))
            }
          </div>
        ))
      }
    </MitraCard>
  )
}

export default BenefitDetails
