import { createRef, Component } from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import PolicyActions from '../../redux/policy/action'
import { Modal, InnerForm, CustomText, Button } from '../index'
import { get } from 'lodash/object'
import { LANG_STRINGS, ERROR_LANG } from '../../lang'
import { SendQuoatationStyle } from './index.style'
import CircularLoader from '../CircularLoader'
import { CONTRACT_GOLD } from '../../images'
import { AgentColorPallette } from '../../configs/colorPallete'
import { APP_HOST } from '../../configs/url'
import { formatMoney } from '../../helpers/utility'
import { DisplayFlexCCC, Row } from '../../commonStyle/index.style'
import authActions from '../../redux/auth/action'
import { APPLICATION_LANG } from '../../containers/Private/Application/lang'
import {
  getSendQuotationForm,
  QUOTATION_EXTRA_KEYS,
} from '../../constants/quoatation'
import { ANDROID_BRIDGE } from '../../bridges/android'
import { gTagOnSendSendQuotationWA } from '../../tagManager'
import {
  HEALTH_FULL_PROTECTION,
  MARINE_CARGO_PROTECTION,
  PROPERTY_PROTECTION_BASIC,
} from '../../constants/pkgCode'
import { setToLocalStorage } from '../../helpers/localstorage'
import { SEND_QUOTATION_SUCCESS } from '../../constants/cookies'
import { withRouter } from 'react-router-dom'

const { sendQuotation, sendQuotationDraft, resetPolicyStore } = PolicyActions
const { logoutGuardian } = authActions
class SendQuotationModal extends Component {
  static propTypes = {
    showQuotationModal: PropTypes.bool,
    quotation: PropTypes.object,
    pkgDetail: PropTypes.object,
    policyType: PropTypes.string,
    id: PropTypes.string,
    onClose: PropTypes.func,
    draftId: PropTypes.string,
  }

  constructor(props) {
    super(props)
    this.state = {
      email: '',
      isShowQuoteConfirmation: false,
    }
    this.child = createRef()
  }

  componentWillReceiveProps(nextProps) {
    const { sendQuotationError, quotationMsg } = nextProps

    if (sendQuotationError && quotationMsg && quotationMsg !== 'success') {
      NotificationManager.error(quotationMsg || ERROR_LANG.somethingWrong)
      this.props.resetPolicyStore(['quotationMsg'])
    } else if (quotationMsg === 'success') {
      const {
        quotationData = {},
        quotation = {},
        pkgDetail = {},
        id,
      } = nextProps
      setToLocalStorage(SEND_QUOTATION_SUCCESS, {
        id,
        email: this.state.email,
        quotationData,
        quotation,
        pkgDetail,
      })
      // Close the modal after successful quotation
      this.props.onClose(get(quotationData, 'id', ''))
    }
  }

  componentWillUnmount() {
    this.props.resetPolicyStore(['quotationMsg', 'quotationData'])
  }

  handleSubmitQuotation = (e) => {
    if (this.props.isGuardianAgentLogin) {
      this.setState({
        isShowQuoteConfirmation: true,
      })
    } else {
      this.handleSubmitForm(e)
    }
  }

  handleSubmitForm = async (e) => {
    const { quotation = {}, draftId, policyType } = this.props
    const formData = await this.child.current.handleSubmit(e)
    if (!formData) {
      return
    }

    this.setState({
      email: formData.email,
    })
    const finalFormData = {
      ...formData,
      type: policyType,
    }
    delete finalFormData.errorField
    const finalQuotationData = {
      ...quotation,
      customer_data: finalFormData,
      draft_id: draftId,
    }
    if (this.props.providerBranch) {
      finalQuotationData.provider_branch = this.props.providerBranch
    }
    QUOTATION_EXTRA_KEYS.forEach(
      (extraKey) => delete finalQuotationData[extraKey]
    )
    this.props.sendQuotationDraft(finalQuotationData)
  }

  getSharingData = (source) => {
    const { quotationData = {}, quotation = {}, pkgDetail = {} } = this.props
    let totalBill =
      pkgDetail.accessories_sum_insured + pkgDetail.vehicle_sum_insured
    let periodType = LANG_STRINGS.months
    let period = quotation.premium.period
    if (quotation.package_type === PROPERTY_PROTECTION_BASIC) {
      totalBill = pkgDetail.total_sum_insured
    }
    if (quotation?.productCode === HEALTH_FULL_PROTECTION) {
      totalBill = pkgDetail.total_sum_insured
    }
    if (pkgDetail?.package?.code === MARINE_CARGO_PROTECTION) {
      totalBill = pkgDetail.total_sum_insured
      period = 30
      periodType = LANG_STRINGS.days
    }

    const linkOfShare = `${APP_HOST}/customer/policy/${quotationData.id}/?source=${source}`
    let extraData = `Rincian transaksi\nNama Produk: ${pkgDetail.package.product.name}\n`
    extraData += `Penyedia Asuransi: ${pkgDetail.provider.name}\n`
    extraData += `Periode Perlindungan: ${period} ${periodType}\n`
    if (quotation?.discount) {
      extraData += `Diskon: ${formatMoney(quotation.discount, 0)}\n`
    }
    extraData += `Premi: ${formatMoney(pkgDetail.sub_total, 0)}\n`
    extraData += `Jumlah Pertanggungan: ${formatMoney(totalBill, 0)}`

    return `${LANG_STRINGS.quotationShareMsg.replace('XXX', linkOfShare)}\n\n${extraData}`
  }

  handleLogoutGuardianAgent = () => {
    this.props.logoutGuardian(true)
  }

  renderOfferSendEmail = () => {
    return (
      <>
        <CustomText
          color={AgentColorPallette.black}
          size="14px"
          textAlign="center"
        >
          {APPLICATION_LANG.insuranceDetailSentToEmail}
        </CustomText>
        <CustomText
          color={AgentColorPallette.darkGold}
          size="13px"
          textAlign="center"
          bottom="30px"
          weight={800}
        >
          {this.state.email}
        </CustomText>
      </>
    )
  }

  renderQuoteConfirm = () => {
    // here we are rendering the quotation confirm modal
    const { agentDetails, id } = this.props
    return (
      <DisplayFlexCCC>
        <img src={CONTRACT_GOLD} alt="" />
        <CustomText
          color={AgentColorPallette.black}
          size="20px"
          top="25px"
          bottom="25px"
          textAlign="center"
          weight={800}
        >
          {LANG_STRINGS.confirmationOffer}
        </CustomText>
        <CustomText
          color={AgentColorPallette.black}
          bottom="25px"
          size="14px"
          textAlign="center"
        >
          Anda akan melakukan pengiriman penawaran atas nama Mitra&nbsp;
          <span className="golden-text">{`"${agentDetails.name}"`}</span>
        </CustomText>
        <CustomText
          color={AgentColorPallette.black}
          bottom="25px"
          size="14px"
          textAlign="center"
        >
          Seluruh penawaran melalui akun ini akan diarahkan kepada&nbsp;
          <span className="golden-text">{`"${agentDetails.name}"`}</span>&nbsp;
          Komisi yang didapatkan juga akan diberikan kepada&nbsp;
          <span className="golden-text">{`"${agentDetails.name}"`}</span>
        </CustomText>
        <Row justify="space-between" width="100%">
          <Button
            onClick={this.handleLogoutGuardianAgent}
            backgroundColor={AgentColorPallette.blue}
            color={AgentColorPallette.white}
          >
            {LANG_STRINGS.exit}
          </Button>
          &nbsp;&nbsp;&nbsp;&nbsp;
          <Button onClick={this.handleSubmitForm} id={`${id}-sendConfirmation`}>
            {LANG_STRINGS.send}
          </Button>
        </Row>
      </DisplayFlexCCC>
    )
  }

  render() {
    const {
      showQuotationModal,
      onClose,
      quotationLoading,
      quotationData,
      id,
      remark = LANG_STRINGS.sendQuotationSendToCustomerRemark,
    } = this.props
    const { isShowQuoteConfirmation } = this.state

    return (
      <Modal
        heading={LANG_STRINGS.sendOffer}
        isOpen={showQuotationModal}
        onClose={() => onClose(get(quotationData, 'id', ''))}
      >
        <CircularLoader isLoading={quotationLoading}>
          <SendQuoatationStyle>
            {
              <>
                <div className={isShowQuoteConfirmation ? '' : 'hidden'}>
                  {this.renderQuoteConfirm()}
                </div>
                <div className={isShowQuoteConfirmation ? 'hidden' : ''}>
                  <InnerForm
                    formData={getSendQuotationForm()}
                    ref={this.child}
                  />
                  <p>
                    <b>Catatan:</b> {remark}
                  </p>
                  <Button
                    className="submit-button"
                    onClick={this.handleSubmitQuotation}
                    id={id}
                  >
                    {LANG_STRINGS.sendNow}
                  </Button>
                </div>
              </>
            }
            <NotificationContainer />
          </SendQuoatationStyle>
        </CircularLoader>
      </Modal>
    )
  }
}

export default connect(
  (state) => ({
    quotationData: state.Policy.quotationData,
    agentDetails: state.User.agentDetails,
    quotationLoading: state.Loading.SEND_QUOTATION,
    sendQuotationError: state.Error.SEND_QUOTATION_DRAFT,
    isGuardianAgentLogin: state.Auth.isGuardianAgentLogin,
    quotationMsg: state.Policy.quotationMsg,
  }),
  {
    sendQuotation,
    sendQuotationDraft,
    logoutGuardian,
    resetPolicyStore,
  }
)(withRouter(SendQuotationModal))
